DE["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload – dein höchster Crit steht hier und wird mit der Gilde geteilt."
DE["1. Drop images and sounds onto the website - everything happens in your browser.\n2. Download the guild pack, unpack it into the AddOns folder, restart WoW.\n3. Share the ZIP in your Discord - everyone in the guild unpacks it the same way."] = "1. Auf der Webseite Bilder und Sounds hineinziehen – alles passiert in deinem Browser.\n2. Gildenpaket herunterladen und in den AddOns-Ordner entpacken, WoW neu starten.\n3. Die ZIP in eurem Discord teilen – alle in der Gilde entpacken sie genauso."
