DE["Oasis can do a lot. Pick what you want to use - the rest stays off for now and can be turned on anytime under 'Discover'."] = "Oasis kann sehr viel. Wähle, was du nutzen willst - der Rest bleibt erstmal aus und lässt sich jederzeit unter 'Entdecken' einschalten."
