DE["Oasis detects your alts automatically once you have logged in with them. Members without Oasis are detected from the guild note (e.g. \"alt of Mira\")."] = "Deine Twinks erkennt Oasis automatisch, sobald du mit ihnen einmal eingeloggt warst. Mitglieder ohne Oasis werden über die Gildennotiz erkannt (z. B. „Twink von Mira“)."
DE["Oasis does not open the map in combat - the waypoint is set, open the map after the fight."] = "Im Kampf öffnet Oasis die Karte nicht - das Ziel ist gesetzt, öffne die Karte nach dem Kampf."
