DE["Oasis exchanges version and error reports realm-wide with other Oasis users. Turn off: Settings > Profile & backup."] = "Oasis tauscht realmweit Version und Fehlerberichte mit anderen Oasis-Nutzern aus. Abschalten: Einstellungen > Profil & Sichern."
