DE["The backdrop of legends"] = "Der Hintergrund der Legenden"
DE["The ban list is empty."] = "Die Bannliste ist leer."
DE["The bank updates whenever someone with Oasis opens the guild vault."] = "Die Bank aktualisiert sich, wenn jemand mit Oasis den Gildentresor öffnet."
DE["The bar is there from login and stays - the X on the window only closes the window."] = "Die Leiste ist ab dem Einloggen da und bleibt – das X am Fenster schließt nur das Fenster."
DE["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"
