DE["The buttons for character, spellbook, talents etc. Keys (C, P, N ...) still work."] = "Die Knöpfe für Charakter, Zauberbuch, Talente usw. Tasten (C, P, N ...) gehen weiter."
DE["The buttons put the command into the chat line - it only runs when you press Enter."] = "Die Knöpfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgeführt."
DE["The catalog is still empty."] = "Der Katalog ist noch leer."
DE["The chat as a text box over the window - for selecting across many lines"] = "Der Chat als Textfeld über dem Fenster – zum Markieren über viele Zeilen"
DE["The chat input was touched by Oasis (e.g. 'Whisper' button), then /target was typed."] = "Die Chat-Eingabe war von Oasis berührt (z. B. „Anflüstern“-Knopf), danach wurde /target eingegeben."
DE["The chat input was touched by Oasis (e.g. 'Whisper' button), then a /cast command was typed there."] = "Die Chat-Eingabe war von Oasis berührt (z. B. „Anflüstern“-Knopf), danach wurde dort ein /cast-Befehl eingegeben."
DE["The chat input was touched by Oasis, then /focus was typed."] = "Die Chat-Eingabe war von Oasis berührt, danach wurde /focus eingegeben."
DE["The chat input was touched by Oasis, then a spell command was typed."] = "Die Chat-Eingabe war von Oasis berührt, danach wurde ein Zauber-Befehl eingegeben."
DE["The client delivers no skills right now - wait a moment after logging in."] = "Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."
DE["The client does not let Oasis enable combat logging - please type /combatlog yourself."] = "Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."
DE["The client has no map for this dungeon (e.g. new Forever dungeons)."] = "Für diesen Dungeon hat der Client keine Karte (z.B. neue Forever-Dungeons)."
DE["The client has no map for this dungeon. Oasis draws one itself as Oasis players walk through it - the more people, the better."] = "Für diesen Dungeon hat der Client keine Karte. Oasis zeichnet sie selbst, sobald Oasis-Spieler den Dungeon ablaufen - je mehr Leute, desto genauer."
DE["The color of legends"] = "Die Farbe der Legenden"
DE["The content of the selected area. The overview shows who is online, what is coming up and what is new."] = "Der Inhalt des gewählten Bereichs. Die Übersicht zeigt, wer online ist, was ansteht und was es Neues gibt."
DE["The crafter is notified right away and gets back to you."] = "Der Handwerker bekommt sofort einen Hinweis und meldet sich."
DE["The customer is told it's ready."] = "Der Auftraggeber bekommt Bescheid, dass es fertig ist."
DE["The dash at the top right collapses Oasis into a slim bar. It remembers its position and snaps to the top edge of the screen."] = "Mit dem Strich oben rechts klappst du Oasis zu einer schmalen Leiste ein. Sie merkt sich ihre Position; oben am Bildschirmrand rastet sie ein."
DE["The dungeon compass: which dungeon fits, what drops there for you."] = "Der Dungeonkompass: welcher Dungeon passt, was droppt dort für dich."
DE["The enemy was not in front of you. It was behind you. The whole time."] = "Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."
DE["The essentials"] = "Das Wichtigste"
DE["The essentials at a glance"] = "Das Wichtigste auf einen Blick"
DE["The fight was locked at first and was recorded afterwards."] = "Der Kampf war erst gesperrt und wurde nachträglich ausgewertet."
DE["The first 20 stamina give 1 health each, every further point 10."] = "Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."
DE["The first animated guild emojis"] = "Die ersten animierten Gilden-Emojis"
DE["The floating buff window opens as soon as you join a group"] = "Das schwebende Buff-Fenster geht auf, sobald du in eine Gruppe kommst"
DE["The floating window can no longer be moved by accident"] = "Das schwebende Fenster lässt sich nicht mehr versehentlich verschieben"
DE["The full history with emojis - Oasis fetches missed messages when you log in"] = "Der ganze Verlauf mit Emojis - verpasste Nachrichten holt Oasis beim Einloggen nach"
DE["The full license texts are in the Oasis folder: CREDITS.txt, LICENSE and LICENSE-MIT.txt."] = "Die vollständigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."
DE["The game gives no position here."] = "Hier liefert das Spiel keine Position."
DE["The game provides no map position here."] = "Hier liefert das Spiel keine Kartenposition."
DE["The group leader can make you an assistant."] = "Der Gruppenanführer kann dich zum Assistenten machen."
DE["The guild bank hasn't been read yet"] = "Die Gildenbank wurde noch nicht gelesen"
DE["The guild bank hasn't been read yet. As soon as someone with Oasis opens the guild vault, everything shows up here – for the whole guild."] = "Die Gildenbank wurde noch nie gelesen. Sobald jemand mit Oasis den Gildentresor öffnet, steht hier alles – für die ganze Gilde."
DE["The guild can see whom you react to. Default: off"] = "Die Gilde sieht dabei, wem du antwortest. Standard: aus"
DE["The guild isn't looking for anything from this dungeon."] = "Die Gilde sucht gerade nichts aus diesem Dungeon."
DE["The guild leadership has disabled open invites - challenge someone directly."] = "Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."
DE["The guild leadership has disabled the partner search."] = "Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."
DE["The guild leadership hasn't released a pack yet."] = "Die Gildenleitung hat noch kein Paket freigegeben."
DE["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zählen auch Raidleiter und Assistenten."
DE["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zählen auch Raidleiter und Assistenten."
DE["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zählt auch der Raidleiter."
DE["The guild leadership only allows group searches from a higher rank."] = "Die Gildenleitung erlaubt Gruppensuchen erst ab einem höheren Rang."
DE["The guild leadership only allows polls from a higher rank."] = "Die Gildenleitung erlaubt Umfragen erst ab einem höheren Rang."
DE["The guild leadership released version %d with custom emojis and sounds. Ask for the ZIP and unpack it into the AddOns folder."] = "Die Gildenleitung hat Version %d mit eigenen Emojis und Sounds freigegeben. Frag nach der ZIP und entpacke sie in den AddOns-Ordner."
DE["The guild leadership sets which ranks may do this under Crown > Modules."] = "Die Gildenleitung legt unter Krone > Module fest, welche Ränge das dürfen."
DE["The guild master decides who belongs to the leadership under Crown > Guild."] = "Wer zur Gildenleitung gehört, legt der Gildenmeister unter Krone > Gilde fest."
DE["The guild master sets officer ranks in the guild window."] = "Offiziersränge legt der Gildenmeister im Gildenfenster fest."
DE["The guild needs this:"] = "Die Gilde braucht das:"
DE["The guild sees your achievements in the chronicle"] = "Die Gilde sieht in der Chronik, was du erreicht hast"
DE["The guild sees your fire on the map for %d minutes."] = "Die Gilde sieht dein Feuer %d Minuten auf der Karte."
DE["The guild sees your fire on the map for 15 minutes."] = "Die Gilde sieht dein Feuer 15 Minuten auf der Karte."
DE["The guild sees your invite. As soon as someone joins, the game starts."] = "Die Gilde sieht deine Einladung. Sobald jemand mitspielt, geht es los."
DE["The guild will be notified"] = "Die Gilde bekommt Bescheid"
DE["The guild's Legacy challenges: who has what, who still needs what – and do them together"] = "Legacy-Challenges der Gilde: wer hat was, wer braucht noch was - und gemeinsam erledigen"
DE["The guild's custom emojis and sounds: rank per entry, switch on and off, release, see who has the pack."] = "Eigene Emojis und Sounds der Gilde: Rang je Eintrag, ein- und ausschalten, freigeben, sehen, wer das Paket hat."
DE["The guild's shopping list – anyone who has or can craft something gets notified on loot and in the tooltip"] = "Einkaufsliste der Gilde – wer etwas hat oder bauen kann, bekommt beim Looten und im Tooltip Bescheid"
DE["The hundred"] = "Hundertschaft"
DE["The key opens and closes the Oasis window instead of Blizzard's guild window"] = "Statt Blizzards Gildenfenster öffnet und schließt die Taste das Oasis-Fenster"
