DE["The language pack is not installed - please copy all folders from the Oasis ZIP into AddOns."] = "Das Sprachpaket ist nicht installiert – bitte alle Ordner aus der Oasis-ZIP nach AddOns kopieren."
DE["The last lines of each tab are back after you log in (up to 7 days old, as plain text). They are stored only on your PC."] = "Die letzten Zeilen jedes Reiters stehen nach dem Einloggen wieder da (bis zu 7 Tage alt, als einfacher Text). Gespeichert wird nur bei dir."
