DE["The matching character statistic has not been found yet."] = "Die passende Charakterstatistik wurde noch nicht gefunden."
DE["The minimap button or /oa opens Oasis. The dash at the top right turns the window into a slim bar."] = "Der Minimap-Knopf oder /oa öffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."
