DE["%s - Ctrl+C copies the download link:"] = "%s - Strg+C kopiert den Download-Link:"
DE["Switched off - turn it on in the AddOn list (character screen)"] = "Ausgeschaltet - in der AddOn-Liste (Charakterauswahl) einschalten"
DE["Not installed - click for the download link"] = "Nicht installiert - Klick zeigt den Download-Link"
DE["Turn on"] = "Einschalten"
DE["Switched on. It loads after a reload of the interface."] = "Eingeschaltet. Es lädt nach einem Neuladen der Oberfläche."
DE["This add-on is installed but switched off in the AddOn list."] = "Dieses Addon ist installiert, aber in der AddOn-Liste ausgeschaltet."
DE["Not installed. Download it from CurseForge (Ctrl+C copies the link), unpack it into Interface/AddOns and restart the game."] = "Nicht installiert. Lade es von CurseForge (Strg+C kopiert den Link), entpacke es nach Interface/AddOns und starte das Spiel neu."
DE["Only the base: the add-ons count as not installed. /reload to apply, /oa nurbasis again to undo."] = "Nur die Basis: die Zusatz-Addons gelten als nicht installiert. /reload zum Anwenden, nochmal /oa nurbasis zum Zurücknehmen."
DE["Add-ons are used again. /reload to apply."] = "Zusatz-Addons werden wieder genutzt. /reload zum Anwenden."
DE["Optional add-on for OASIS"] = "Optionales Addon für OASIS"
DE["Download link - Ctrl+C copies it"] = "Download-Link - Strg+C kopiert ihn"
DE["Select link"] = "Link markieren"
DE["This add-on is installed but switched off in the AddOn list. Switch it on here - it is there after a reload."] = "Dieses Addon ist installiert, aber in der AddOn-Liste ausgeschaltet. Schalte es hier ein - nach dem Neuladen ist es da."
DE["1.  Copy the link and open it in your browser"] = "1.  Link kopieren und im Browser öffnen"
DE["2.  Download and unpack it into Interface/AddOns"] = "2.  Herunterladen und nach Interface/AddOns entpacken"
DE["3.  Restart the game - the area appears by itself"] = "3.  Spiel neu starten - der Bereich erscheint von selbst"
